#!/usr/bin/env python3
"""Apply the verified v170 homepage and button delta to the verified v168 website."""
import argparse
import base64
import gzip
import hashlib
import json
from pathlib import Path
import shutil

BASELINE_ARCHIVE_SHA256 = '92c7225bb4df16cf25360cead54deb7d135488bfb9fa4e3e770845e476a33f11'
PAYLOAD = ''

def sha(data):
    return hashlib.sha256(data).hexdigest()

def tree(root):
    result = {}
    for file in root.rglob('*'):
        if file.is_symlink():
            raise ValueError('Symlink outside release scope.')
        if file.is_file():
            result[file.relative_to(root).as_posix()] = sha(file.read_bytes())
    return result

def build(source, output):
    source, output = source.resolve(), output.resolve()
    if not source.is_dir() or output.exists() or source == output or source in output.parents or output in source.parents:
        raise ValueError('Use a baseline directory and a new separate output directory.')
    spec = json.loads(gzip.decompress(base64.b64decode(PAYLOAD, validate=True)))
    if tree(source) != spec['baseline']:
        raise ValueError('The complete input tree does not match the verified v168 baseline.')
    updates = {}
    for name, encoded in spec['files'].items():
        updates[name] = base64.b64decode(encoded, validate=True)
    for name, edits in spec['edits'].items():
        text = (source / name).read_text(encoding='utf-8')
        limit = len(text)
        for start, end, replacement in reversed(edits):
            if not 0 <= start <= end <= limit:
                raise ValueError('Invalid text edit.')
            text = text[:start] + replacement + text[end:]
            limit = start
        updates[name] = text.encode('utf-8')
    for name, data in updates.items():
        path = Path(name)
        if path.is_absolute() or '..' in path.parts or sha(data) != spec['output'].get(name):
            raise ValueError('Invalid path or output checksum: ' + name)
    shutil.copytree(source, output)
    try:
        for name, data in updates.items():
            target = output / name
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_bytes(data)
        if tree(output) != spec['output'] or tree(source) != spec['baseline']:
            raise ValueError('Output mismatch or baseline changed during preparation.')
    except Exception:
        shutil.rmtree(output)
        raise
    print(json.dumps({'release':'v170','result':'PASS','files':len(spec['output']),'changed':sorted(updates),'sourceModified':False}, sort_keys=True))

if __name__ == '__main__':
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--source', type=Path, required=True)
    parser.add_argument('--output', type=Path, required=True)
    args = parser.parse_args()
    build(args.source, args.output)
